var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Tests/MainStage/HumanCannon/HumanCannon.unity",UnityEditor.SceneManagement.OpenSceneMode.Additive);
try{var t=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CurtainCall.HumanCannon.HumanCannonTrampoline>(true)).First();return t.GetComponentsInChildren<UnityEngine.Collider>(true).Select(c=>new{c.name,type=c.GetType().Name,c.enabled,c.isTrigger,position=c.transform.localPosition.ToString(),size=c.bounds.size.ToString()}).ToArray();}finally{UnityEditor.SceneManagement.EditorSceneManager.CloseScene(scene,true);}
